from bench.language import NODE_CLASS_BY_TYPE, VERSION, NodeType
from bench.utils.utils import format_python

from .map import map_builtin_node_to_database_table


def gen_schema():
    """Generate the .py custom SQL schema describing the current Bench types."""
    chunks: list[str] = [
        "# This file was automatically generated by Bench. DO NOT EDIT!",
        "from .core import PrimitiveType, DatabaseTable, DatabaseConstraint, DatabaseConstraintType, DatabaseIndex, DatabaseIndexType, DatabaseColumn",
        f'VERSION = "{VERSION}"',
    ]
    for node_t in NodeType:
        if node_t == NodeType.CUSTOM_NODE_INSTANCE:
            continue
        node_cls = NODE_CLASS_BY_TYPE[node_t]
        table = map_builtin_node_to_database_table(node_cls)
        const_name = f"{node_cls.metatype.name}_TABLE"
        table_def = f"{const_name} = {table.source_repr()}"
        chunks.append(table_def)
    source = "\n\n".join(chunks)
    source = format_python(source)
    return source
